Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <cstdio>
#include <vector>
#include <cmath>

using namespace std;

int main() {
    int p, k;
    scanf("%d %d", &p, &k);

    vector<int> parent(p), size(p,1);
    for(int i=0; i<p; ++i) parent[i]=i;

    auto find_root = [&](int u) {
        while(parent[u] != u) {
            parent[u] = parent[parent[u]];
            u = parent[u];
        }
        return u;
    };

    auto union_sets = [&](int u, int v) {
        u = find_root(u);
        v = find_root(v);
        if(u != v) {
            size[u] += size[v];
            parent[v] = u;
        }
    };

    auto mod_pow = [&](long long base, long long exp, long long mod) {
        long long result=1;
        while(exp>0) {
            if(exp & 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>=1;
        }
        return result;
    };

    auto isok = [&](long long a, long long b, long long p) {
        long long res=1;
        while(b>0) {
            if(b & 1) res = res * a % p;
            a = a * a % p;
            b >>=1;
        }
        return res==1 ? p : 1;
    };

    if(k==0) {
        printf("%lld", mod_pow(p, p-1, 1000000007));
        return 0;
    }

    for(int i=0; i<p; ++i) {
        parent[i]=i;
    }

    for(int i=0; i<p; ++i) {
        int v = (long long)k * i % p;
        union_sets(v, i);
    }

    long long answer=1;
    for(int i=0; i<p; ++i) {
        if(find_root(i)==i) {
            answer = (answer * (long long)isok(k, size[i], p)) % 1000000007;
        }
    }

    printf("%lld", answer);
    return 0;
}
